  result_status: 'technical_error',
  error_code: 'SMS_RESULT_UPDATE_FAILED',
  source_message_id: item.correlation_id ?? item.message_id ?? null,
  message_id: item.message_id ?? null,
  idempotency_key: item.idempotency_key ?? null,
  processing_status: item.processing_status ?? 'not_completed',
  success_confirmation: false,
  retry_safe: true,
} };

const segmentItems = $('Split SMS into Segments').all();
if (!segmentItems.length) {
  throw new Error('SMS_SEGMENTS_UNAVAILABLE');
}

const segmentByKey = new Map();
for (const item of segmentItems) {
  const segment = item.json ?? {};
  const key = segment.idempotency_key;
  if (typeof key !== 'string' || key.trim().length === 0) {
    throw new Error('SMS_SEGMENT_IDEMPOTENCY_KEY_MISSING');
  }
  if (segmentByKey.has(key)) {
    throw new Error('SMS_SEGMENT_IDEMPOTENCY_KEY_NOT_UNIQUE');
  }
  segmentByKey.set(key, segment);
}

const existingByKey = new Map();
for (const item of $input.all()) {
  let row = item.json;
  if (row && typeof row === 'object' && !Array.isArray(row) &&
      typeof row.idempotency_key !== 'string' &&
      row.json && typeof row.json === 'object' && !Array.isArray(row.json)) {
    row = row.json;
  }
  if (!row || typeof row !== 'object' || Array.isArray(row) || Object.keys(row).length === 0) {
    continue;
  }

  const key = row.idempotency_key;
  if (typeof key !== 'string' || key.length === 0 || !segmentByKey.has(key)) {
    throw new Error('SMS_OUTBOUND_LOOKUP_KEY_MISMATCH');
  }
  if (row.direction !== 'outbound' ||
      row.id === undefined || row.id === null ||
      String(row.id).trim().length === 0) {
    throw new Error('SMS_OUTBOUND_LOOKUP_RECORD_INVALID');
  }
  if (existingByKey.has(key)) {
    throw new Error('SMS_OUTBOUND_RECORD_NOT_UNIQUE');
  }
  existingByKey.set(key, row);
}

return segmentItems.map((item) => {
  const source = item.json ?? {};
  const key = source.idempotency_key;
  const segment = { ...source };
  delete segment.id;
  delete segment.createdAt;
  delete segment.updatedAt;

  const existing = existingByKey.get(key);
  const output = existing
    ? {
        ...segment,
        ...existing,
        send_allowed: source.send_allowed === true,
        part_number: source.part_number ?? null,
        part_count: source.part_count ?? null,
        recipient_department: source.recipient_department ?? null,
        existing_outbound: true,
      }
    : { ...segment, existing_outbound: false };

  return { json: output, pairedItem: { item: 0 } };
});
